using System.Text.Json;
using RepoDocsCli.Features.Docs;

namespace RepoDocsCli.Tests.Cli;

public class ImportCommandTests
{
    TempRepo repo = null!;

    [SetUp]
    public void SetUp() => repo = new TempRepo();

    [TearDown]
    public void TearDown() => repo.Dispose();

    const string RootClaudeMd =
        """
        # Guide

        @docs/extra.md

        ## Style

        - Never use regions.
        - Use file-scoped namespaces.

        ## Billing

        Invoices are stored in cents. Round once.

        <!-- docs:begin (generated by docs render; edit .repo-docs instead) -->
        ## Repo

        ### repo/old: Generated text
        <!-- docs:end -->
        """;

    void WriteFile(string repoPath, string content)
    {
        var path = Path.Combine(repo.Root, repoPath);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content);
    }

    void InitWithBilling()
    {
        repo.Store.Initialize();
        repo.WriteDocsFile("billing.yaml", "feature: billing\nstatus: shipped\nwhen:\n  paths:\n    - App/Billing/\n");
    }

    [Test]
    public void ImportsRootSectionsIntoRepoAndFeatureNamedByHeading()
    {
        InitWithBilling();
        WriteFile("CLAUDE.md", RootClaudeMd);

        var result = repo.Run("import");

        Assert.That(result.ExitCode, Is.Zero, result.Errors);
        var snapshot = repo.Store.Load();
        Assert.That(snapshot.Repo.Entries.Select(entry => (entry.Id, entry.Kind, entry.Summary)), Is.EqualTo(new[]
        {
            ("never-use-regions", "rule", "Never use regions"),
            ("use-file-scoped-namespaces", "fact", "Use file-scoped namespaces"),
        }));
        var billing = snapshot.Find("billing")!.Entries.Single();
        Assert.That((billing.Id, billing.Summary, billing.Body), Is.EqualTo(("invoices-are-stored-in-cents", "Invoices are stored in cents", "Round once.")));
        Assert.That(billing.Created, Is.Not.Null);
        Assert.That(snapshot.Repo.Entries.Select(entry => entry.Summary), Has.None.Contains("Generated"));
        Assert.That(result.Output, Does.Contain("@docs/extra.md (CLAUDE.md:3)"));
        Assert.That(result.Output, Does.Contain("run docs render"));
        Assert.That(File.ReadAllText(Path.Combine(repo.Root, "CLAUDE.md")), Is.EqualTo(RootClaudeMd));
    }

    [Test]
    public void NestedFilesMatchFeaturesByLongestPathPrefix()
    {
        InitWithBilling();
        repo.WriteDocsFile("app.yaml", "feature: app\nwhen:\n  paths:\n    - App/\n");
        WriteFile("App/Billing/Invoices/CLAUDE.md", "## Totals\n\nTotals include VAT.\n");
        WriteFile("App/Other/AGENTS.md", "## Startup\n\nStartup reads appsettings.\n");

        var result = repo.Run("import");

        Assert.That(result.ExitCode, Is.Zero, result.Errors);
        Assert.That(repo.Store.LoadFeature("billing").Entries.Select(entry => entry.Id), Is.EqualTo(new[] { "totals" }));
        Assert.That(repo.Store.LoadFeature("app").Entries.Select(entry => entry.Id), Is.EqualTo(new[] { "startup" }));
        Assert.That(repo.Store.Load().Features.Select(feature => feature.Id), Is.EqualTo(new[] { "app", "billing" }));
    }

    [Test]
    public void NestedFileWithoutAMatchingFeatureCreatesOneNamedAfterTheFolder()
    {
        repo.Store.Initialize();
        WriteFile("Web/UserAccounts/CLAUDE.md", "# User accounts\n\nAccounts are soft-deleted.\n\n## Login\n\nLogin uses cookies.\n");

        var json = JsonDocument.Parse(repo.Run("import", "--json").Output).RootElement;

        var feature = repo.Store.LoadFeature("user-accounts");
        Assert.That(feature.When.Paths, Is.EqualTo(new[] { "Web/UserAccounts/" }));
        Assert.That(feature.Status, Is.EqualTo(FeatureStatus.Shipped));
        Assert.That(feature.Created, Is.Not.Null);
        Assert.That(feature.Entries.Select(entry => (entry.Id, entry.Summary)), Is.EqualTo(new[]
        {
            ("accounts-are-soft-deleted", "Accounts are soft-deleted"),
            ("login", "Login"),
        }));
        Assert.That(json.GetProperty("createdFeatures").EnumerateArray().Select(id => id.GetString()), Is.EqualTo(new[] { "user-accounts" }));
    }

    [Test]
    public void EntryIdsAreUniqueWithinAFeature()
    {
        repo.Store.Initialize();
        repo.WriteDocsFile("repo.yaml", "entries:\n  - id: setup\n    kind: fact\n    summary: Setup\n    body: Old.\n");
        WriteFile("CLAUDE.md", "## Setup\n\nInstall the SDK.\n\n## Other\n\n### Setup\n\nRun init.\n");

        repo.Run("import");

        Assert.That(repo.Store.Load().Repo.Entries.Select(entry => entry.Id), Is.EqualTo(new[] { "setup", "setup-2", "setup-3" }));
    }

    [Test]
    public void DryRunWritesNothing()
    {
        repo.InitGit();
        repo.Store.Initialize();
        WriteFile("CLAUDE.md", RootClaudeMd);
        WriteFile("Web/Search/CLAUDE.md", "## Index\n\nRebuild nightly.\n");
        var before = Directory.GetFiles(repo.Folder).Select(File.ReadAllText).ToList();

        var result = repo.Run("import", "--dry-run");

        Assert.That(result.ExitCode, Is.Zero, result.Errors);
        Assert.That(result.Output, Does.Contain("Would import 4 entries from 2 files:"));
        Assert.That(result.Output, Does.Contain("search/index fact Index (Web/Search/CLAUDE.md:1)"));
        Assert.That(result.Output, Does.Contain("Would create features: search"));
        Assert.That(Directory.GetFiles(repo.Folder).Select(File.ReadAllText), Is.EqualTo(before));
        Assert.That(repo.Git("diff", "--cached", "--name-only"), Does.Not.Contain("search.yaml"));
    }

    [Test]
    public void ImportingTwiceSkipsEntriesAlreadyPresent()
    {
        InitWithBilling();
        WriteFile("CLAUDE.md", RootClaudeMd);
        WriteFile("Web/Search/CLAUDE.md", "## Index\n\n- Rebuild nightly.\n- Never index drafts.\n\n```sh\nindex --all\n```\n");
        repo.Run("import");
        var files = Directory.GetFiles(repo.Folder, "*.yaml").ToDictionary(path => path, File.ReadAllText);

        var json = JsonDocument.Parse(repo.Run("import", "--json").Output).RootElement;

        Assert.That(json.GetProperty("imported").GetArrayLength(), Is.Zero);
        Assert.That(json.GetProperty("skipped").GetArrayLength(), Is.EqualTo(4));
        Assert.That(json.GetProperty("skipped")[0].GetProperty("address").GetString(), Is.EqualTo("repo/never-use-regions"));
        Assert.That(Directory.GetFiles(repo.Folder, "*.yaml").ToDictionary(path => path, File.ReadAllText), Is.EqualTo(files));
    }

    [Test]
    public void JsonHasTheDocumentedShape()
    {
        repo.Store.Initialize();
        WriteFile("CLAUDE.md", RootClaudeMd);

        var result = repo.Run("import", "--dry-run", "--json");
        var json = JsonDocument.Parse(result.Output).RootElement;

        Assert.That(result.Errors, Is.Empty);
        Assert.That(json.EnumerateObject().Select(property => property.Name),
            Is.EqualTo(new[] { "dryRun", "sources", "imported", "skipped", "createdFeatures", "imports" }));
        Assert.That(json.GetProperty("dryRun").GetBoolean(), Is.True);
        Assert.That(json.GetProperty("sources").EnumerateArray().Select(source => source.GetString()), Is.EqualTo(new[] { "CLAUDE.md" }));
        var first = json.GetProperty("imported")[0];
        Assert.That(first.EnumerateObject().Select(property => property.Name), Is.EqualTo(new[] { "address", "kind", "summary", "source", "line" }));
        Assert.That(first.GetProperty("address").GetString(), Is.EqualTo("repo/never-use-regions"));
        Assert.That(first.GetProperty("kind").GetString(), Is.EqualTo("rule"));
        Assert.That(first.GetProperty("source").GetString(), Is.EqualTo("CLAUDE.md"));
        Assert.That(first.GetProperty("line").GetInt32(), Is.EqualTo(7));
        Assert.That(json.GetProperty("skipped").GetArrayLength(), Is.Zero);
        var import = json.GetProperty("imports")[0];
        Assert.That((import.GetProperty("source").GetString(), import.GetProperty("line").GetInt32(), import.GetProperty("text").GetString()),
            Is.EqualTo(("CLAUDE.md", 3, "@docs/extra.md")));
    }

    [Test]
    public void ExplicitFilesAreTheOnlySources()
    {
        repo.Store.Initialize();
        WriteFile("CLAUDE.md", RootClaudeMd);
        WriteFile("notes/conventions.md", "## Naming\n\nNever abbreviate.\n");

        var json = JsonDocument.Parse(repo.Run("import", Path.Combine(repo.Root, "notes", "conventions.md"), "--json").Output).RootElement;

        Assert.That(json.GetProperty("sources").EnumerateArray().Select(source => source.GetString()), Is.EqualTo(new[] { "notes/conventions.md" }));
        Assert.That(repo.Store.LoadFeature("notes").Entries.Single().Kind, Is.EqualTo("rule"));
    }

    [Test]
    public void AMissingFileArgumentIsAUsageError()
    {
        repo.Store.Initialize();

        var result = repo.Run("import", Path.Combine(repo.Root, "missing.md"));

        Assert.That(result.ExitCode, Is.EqualTo(ExitCodes.Usage));
        Assert.That(result.Errors, Does.Contain("missing.md"));
    }

    [Test]
    public void UndeclaredGuessedKindsFallBackToFact()
    {
        repo.Store.Initialize();
        repo.WriteDocsFile("config.yaml", "version: 1\nkinds:\n  fact: {}\n  note: {}\n");
        WriteFile("CLAUDE.md", "## Style\n\nNever use regions.\n");

        repo.Run("import");

        Assert.That(repo.Store.Load().Repo.Entries.Single().Kind, Is.EqualTo("fact"));
    }

    [Test]
    public void NewFeatureFilesAreGitAdded()
    {
        repo.InitGit();
        repo.Store.Initialize();
        repo.Git("add", "-A");
        repo.Git("commit", "-q", "-m", "docs");
        WriteFile("Web/Search/CLAUDE.md", "## Index\n\nRebuild nightly.\n");

        repo.Run("import");

        Assert.That(repo.Git("diff", "--cached", "--name-only"), Is.EqualTo(".repo-docs/search.yaml\n"));
        Assert.That(repo.Git("status", "--porcelain", "--", ".repo-docs"), Is.EqualTo("A  .repo-docs/search.yaml\n"));
    }

    [Test]
    public void BrokenDocsFilesStopTheImport()
    {
        repo.Store.Initialize();
        repo.WriteDocsFile("repo.yaml", "entries: [unclosed");
        WriteFile("CLAUDE.md", RootClaudeMd);

        var result = repo.Run("import");

        Assert.That(result.ExitCode, Is.EqualTo(ExitCodes.ValidationFailed));
        Assert.That(result.Errors, Does.Contain("repo.yaml"));
        Assert.That(repo.ReadDocsFile("repo.yaml"), Is.EqualTo("entries: [unclosed"));
    }

    [Test]
    public void ImportWithoutRepoDocsIsAUsageError()
    {
        WriteFile("CLAUDE.md", RootClaudeMd);

        var result = repo.Run("import");

        Assert.That(result.ExitCode, Is.EqualTo(ExitCodes.Usage));
        Assert.That(result.Errors, Does.Contain("docs init"));
        Assert.That(repo.Store.IsInitialized, Is.False);
    }
}
